    public void registerRecipeCatalysts(IRecipeCatalystRegistration registration) {
        registration.addRecipeCatalyst(new ItemStack((ItemLike)AMBlockRegistry.CAPSID.get()), new RecipeType[]{CAPID_RECIPE_TYPE});
    }
}

